        RETURN _pgweave_result;
    END;

END;
$$;

CREATE OR REPLACE FUNCTION orders_award_loyalty_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    _pgweave_traceparent text := current_setting('pgweave.traceparent', true);
    _pgweave_sampled boolean := coalesce(_pgweave_traceparent ~ '^[0-9a-f]{2}-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f][13579bdf]$', false);
    _pgweave_run_id uuid := CASE WHEN _pgweave_sampled THEN gen_random_uuid() END;
    _pgweave_started_at timestamptz := CASE WHEN _pgweave_sampled THEN clock_timestamp() END;
    _pgweave_parent uuid := CASE WHEN _pgweave_sampled THEN nullif(current_setting('pgweave.span', true), '')::uuid END;
    _pgweave_max_depth int := nullif(current_setting('pgweave.max_depth', true), '')::int;
    _pgweave_depth int := CASE WHEN _pgweave_sampled OR _pgweave_max_depth IS NOT NULL THEN set_config('pgweave.depth', (coalesce(nullif(current_setting('pgweave.depth', true), '')::int, 0) + 1)::text, true)::int END;
    _pgweave_config text := CASE WHEN _pgweave_sampled THEN set_config('pgweave.span', _pgweave_run_id::text, true) END;
    _pgweave_rows bigint;
    _pgweave_steps json[] := ARRAY[]::json[];
    _pgweave_found boolean;
BEGIN
    IF _pgweave_depth > _pgweave_max_depth THEN
        RAISE EXCEPTION 'pgweave: % called at depth %, beyond pgweave.max_depth', 'orders_award_loyalty_fn', _pgweave_depth USING ERRCODE = '54001';
    END IF;
    IF _pgweave_sampled THEN
        RAISE NOTICE 'pgweave_log' USING DETAIL = json_build_object('type', 'start', 'run', _pgweave_run_id, 'routine', 'orders_award_loyalty_fn', 'parent', _pgweave_parent, 'depth', _pgweave_depth, 'traceparent', CASE WHEN _pgweave_parent IS NULL THEN left(_pgweave_traceparent, 512) END, 'started_at', _pgweave_started_at)::text;
    END IF;

    UPDATE customers
    SET loyalty_points = loyalty_points + loyalty_points_of(NEW.id)
    WHERE id = NEW.customer_id;
    GET DIAGNOSTICS _pgweave_rows = ROW_COUNT;
    IF _pgweave_sampled THEN _pgweave_steps := array_append(_pgweave_steps, json_build_object('kind', 'UPDATE', 'target', 'customers', 'line', 16, 'row_count', _pgweave_rows, 'offset_ms', 1000 * extract(epoch FROM clock_timestamp() - _pgweave_started_at)::float8)); END IF;
    IF _pgweave_sampled THEN RAISE NOTICE 'pgweave_log' USING DETAIL = json_build_object('type', 'end', 'run', _pgweave_run_id, 'duration_ms', 1000 * extract(epoch FROM clock_timestamp() - _pgweave_started_at)::float8, 'steps', array_to_json(_pgweave_steps), 'error', NULL::text)::text; _pgweave_config := set_config('pgweave.span', coalesce(_pgweave_parent::text, ''), true); END IF;
    IF _pgweave_depth IS NOT NULL THEN _pgweave_config := set_config('pgweave.depth', (_pgweave_depth - 1)::text, true); END IF;
    RETURN NULL;

END;
$$;

CREATE TRIGGER orders_award_loyalty
AFTER UPDATE OF status ON orders
FOR EACH ROW WHEN ((((new.status = 'served') AND (old.status IS DISTINCT FROM 'served')) AND (new.customer_id IS NOT NULL)))
EXECUTE FUNCTION orders_award_loyalty_fn();

DROP FUNCTION award_loyalty();
